def add(domain, question, options, answer, explanation, ref):
    qid = (284 if domain == 3 else 334) + sum(q['Domain'] == domain for q in questions)
    if domain == 4 and qid >= 368:
        qid += 1  # ID 368 retired with the legacy Developer Support question.
    questions.append({'ID': qid, 'Domain': domain, 'QuestionText': question,
                      'Options': options, 'CorrectAnswer': answer,
                      'Explanation': explanation, 'Reference': refs[ref]})

