assert len([q for q in questions if q['Domain'] == 3]) == 50
assert len([q for q in questions if q['Domain'] == 4]) == 49
for q in questions:
    correct = {ord(letter) - ord('A') for letter in (q['CorrectAnswer'] if isinstance(q['CorrectAnswer'], list) else [q['CorrectAnswer']])}
    indexed = list(enumerate(q['Options']))
    random.Random(20261018 + q['ID']).shuffle(indexed)
    q['Options'] = [option for _, option in indexed]
    answers = [chr(ord('A') + i) for i, (original_index, _) in enumerate(indexed) if original_index in correct]
    q['CorrectAnswer'] = answers if isinstance(q['CorrectAnswer'], list) else answers[0]
(ROOT / 'research-d3-d4.json').write_text(json.dumps(questions, ensure_ascii=False, indent=2) + '\n')
